// Original challenges using the manual's scenario/status model; not shipped SC3KU scenarios.
export const SCENARIOS={
 restorePeace:{title:'Restore the peace',months:12,description:'Contain an ongoing riot and sustain three months of low crime, restored homes and a cash reserve within one year.',briefing:'A riot is underway at tile 21, 21. Your town has 224 residents, §2,500, a police station, fire station, jail and landfill. Police funding was cut to 25%, and both the volunteer brigade and station squad were dispatched far away. Open Emergency to recall or reposition squads. Restore Police funding in Civic services so the station can cover its precinct; jail cells do not replace police coverage. Contain any resulting fires, clear rubble and let homes recover. Then sustain three consecutive monthly checks with no active emergency or rubble, at least 224 residents, average crime at most 15, and §1,500 cash. You have twelve months. The calendar pauses during emergency response. Random disasters start off. This is an original challenge for the reconstruction.'},
 learningCity:{title:'A city that learns',months:24,description:'Build complementary adult education services. Reach adult EQ 41 with library and museum access of at least 90%, preserve 224 residents and keep §1,000 within two years.',briefing:'Your town starts with 224 residents, adult education of 40 and §8,000. Roads, electricity and landfill collection are prepared. Build a library and a museum near the existing road network; a 2 × 2 library lot at tile 24, 26 and a 3 × 3 museum lot at tile 28, 22 are suitable. Open Civic services and the education report to compare library and museum access. They provide independent adult learning benefits; more copies of one cannot replace the other. Reach at least 41 adult EQ, at least 90% access to each service, at least 224 residents and a §1,000 reserve within 24 months. Keep education funded and allow the calendar to run: learning takes time, and migration and aging affect averages. Pro Reading can help. Random disasters start off. This is an original challenge for the reconstruction.'},
 growingUpward:{title:'Growing upward',months:24,description:'Bring water to a low-rise town and grow to 700 residents with 25 developed medium-density home tiles within two years.',briefing:'Your town starts with 224 residents, §10,000, roads, power and landfill. Add water and rezone existing residential, commercial and industrial areas to medium density: homes need jobs as they grow. Two pumping sites lie west of the freshwater lake at tiles 35, 10 and 35, 11. Connect power down column 35 to the existing grid at row 27. Run pipes from 35, 10 to 35, 27, then west to 23, 27 and along column 23 between rows 15 and 31. Use Zone development to check water, land value and demand. Reach 700 residents, develop 25 residential tiles to at least medium density, keep those homes watered and powered, and retain §5,000 within 24 months. Random disasters start off. This is an original challenge for the reconstruction.'},
 roomToGrow:{title:'Room to grow',months:12,description:'A city of 25,000 has reached its residential limit. Create capacity for 26,000 and welcome at least 200 more residents within a year.',briefing:'This 96 × 96 city starts at its residential capacity of 25,000, with 100 vacant home sites, wind power, industry, roads and landfill already prepared. Low-density homes can start without water. The treasury holds §20,000. Open City desk → Zone development to review capacity. Parks and recreation create room for new residents; a clear site begins at tile 86, 3 near the northeast corner, or choose your own locations. Raise residential capacity to at least 26,000, grow to 25,200 residents and keep at least §5,000 within twelve months. More capacity does not guarantee demand or services: watch the budget, power and waste as the town grows. Random disasters start off. This is an original challenge for the reconstruction.'},
 firstRepayment:{title:'The first repayment',months:12,description:'Prepare for a §3,750 loan payment in twelve months. Keep 224 residents, sound roads and §500 after the payment without taking another loan.',briefing:'Your town starts with 224 residents, §2,500 cash and a §25,000 loan issued this month. Its first annual payment of §3,750 is due in January 1951. The borrowed capital has already been spent on the town. Open Budget and meet Mortimer to compare operating income with the repayment calendar. Adjust taxes, grow revenue or manage spending, but preserve at least 224 residents and road condition of 80% when the payment arrives. Finish the twelve months with at least §500 cash after paying. Taking any additional loan disqualifies the challenge, even if it is later repaid. The original loan remains outstanding after this first payment; nine annual payments still follow. Landfill collection is prepared and random disasters start off.'},
 waterRecovery:{title:'Water under pressure',months:24,description:'Restore a broken water network and sustain six months of full water service, at least 224 residents and a §5,000 reserve.',briefing:'Your town starts with 224 residents and §10,000. Its freshwater pumping station still works, but the trunk pipe is broken at map coordinates 25, 17. An aging emergency water tower cannot supply the entire lower town. Open Utilities to find shortages and switch to Water view to inspect the break. Reconnect the trunk pipe, or provide another viable supply. Keep every lot’s water demand served, preserve at least 224 residents, and hold §5,000 for six consecutive monthly checks within two years. Previously watered buildings can abandon if service is not restored promptly. Landfill collection is prepared; random disasters start off.'},
 roadless:{title:'Roadless Paradise',months:24,manualAdaptation:true,description:'Keep a rail-served town free of roads for two years. Adapted from the manual’s Scenario Creator tutorial.',briefing:'This original prepared town uses rail stations to connect homes and workplaces. Power, pipes and water towers are supplied. Keep the road count at zero for 24 months; any road present at a monthly check ends the challenge. Expand around stations and watch transit funding, utilities and the budget. Highway tiles do not count as roads in this tutorial rule. Waste collection still requires road access in this reconstruction, so monitor the resulting pollution as you plan. The manual checks weekly; this adaptation checks monthly and uses a new town layout because the original city file is not included in the manual.'},
 harbor:{title:'The harbor wakes',months:36,description:'Reconnect a dormant harbor, grow to 400 residents, and sustain six months of shipping with a §5,000 reserve.',briefing:'Your coastal town starts with 224 residents and §12,500. The developed harbor at map coordinates 11, 21 has no water: reconnect the missing pipe at 20, 21 in the Water view. The pumping station and the rest of the pipe route already exist. Keep the original harbor supplied with power, water and road access, expand housing and jobs, and maintain 400 residents plus §5,000 for six consecutive months. Ships appear when the harbor operates. Random disasters start off.'},
 pollution:{title:'A cleaner legacy',months:36,description:'Retire a toxic-waste business, grow to 400 residents, and hold a cleaner city with a cash reserve for six consecutive months within three years.',briefing:'Your town starts with a Toxic Waste Conversion Plant paying §300/month and §10,000 in the treasury. Demolish the plant, keep average zoned-land air pollution at 15 or below, house at least 400 residents, and retain §5,000. Hold all four conditions for six consecutive monthly checks. Removing the plant loses its income: grow the tax base and watch spending. Random disasters start off.'},
 growth:{title:'A town takes root',months:60,description:'Turn empty coastal land into a town of 400 residents within five years. Finish with a nonnegative treasury and power for every occupied lot.',briefing:'Lay roads and zone all three RCI types. Supply electricity, collect waste, and expand the tax base. Empty zones do not count as occupied lots.'},
 recovery:{title:'After the sirens',months:24,description:'Lead a starter town through a fire in month 3. Contain it, clear all rubble, and restore at least 224 residents within two years.',briefing:'You have two months to prepare. Water and fire stations help, but the volunteer unit is always available. After the fire, restore utilities and let cleared residential zones rebuild.'},
 streets:{title:'The road back',months:36,description:'Repair a neglected starter town and maintain six consecutive months with sound roads, at least 200 residents, an operating surplus and a nonnegative treasury.',briefing:'Road funding starts at 25% and road condition at 15%. Restore funding in Budget. Repairs take time. Track the consecutive-month objective; a missed condition resets the streak.'}
};
export const waterRecoveryReady=c=>c.stats.population>=224&&c.funds>=5000&&c.stats.waterDemand>0&&c.stats.waterDemand-c.stats.waterUsed<1e-7;
export const harborReady=c=>c.stats.facilityPlots.some(p=>p.type==='seaport'&&p.root===20*48+10&&p.operating);
const occupied=c=>c.tiles.filter(t=>['residential','commercial','industrial'].includes(t.type)&&t.level>0);
export function scenarioGoals(c){const s=c.scenario;if(!s)return[];if(s.status!=='playing'&&s.resultGoals)return captureResultGoals(s.resultGoals);if(s.id==='custom')return customGoals(c);const live=occupied(c),powered=live.length>0&&live.every(t=>t.powered);const goal=(title,done,detail)=>({title,done,detail});
 if(s.id==='restorePeace')return[goal('Sustain peace for three months',s.streak>=3,`${s.streak} / 3 consecutive months`),goal('End the emergency',c.emergency.contained>=1&&!c.emergency.active,c.emergency.active?'Emergency response in progress':'Emergency ended'),goal('Clear all rubble',c.stats.rubbleTiles===0,`${c.stats.rubbleTiles} damaged tiles`),goal('Restore 224 residents',c.stats.population>=224,`${c.stats.population} / 224 residents`),goal('Reduce average crime to 15',c.stats.averageCrime<=15,`${c.stats.averageCrime.toFixed(1)} / 15`),goal('Keep a §1,500 reserve',c.funds>=1500,`§${Math.round(c.funds).toLocaleString()} treasury`)];
 if(s.id==='learningCity')return[goal('Raise adult education to 41',c.civic.adultEducation>=41,`${c.civic.adultEducation.toFixed(2)} / 41 adult EQ`),goal('Provide library access to 90% of adults',c.stats.libraryEducationCoverage>=90,`${c.stats.libraryEducationCoverage.toFixed(1)}% / 90% library access`),goal('Provide museum access to 90% of adults',c.stats.museumEducationCoverage>=90,`${c.stats.museumEducationCoverage.toFixed(1)}% / 90% museum access`),goal('Preserve at least 224 residents',c.stats.population>=224,`${c.stats.population} / 224 residents`),goal('Keep a §1,000 reserve',c.funds>=1000,`§${Math.round(c.funds).toLocaleString()} treasury`)];
 if(s.id==='growingUpward'){const homes=c.tiles.filter(t=>t.type==='residential'&&t.level>=2);return[goal('House at least 700 residents',c.stats.population>=700,`${c.stats.population} / 700 residents`),goal('Develop 25 medium-density home tiles',homes.length>=25,`${homes.length} / 25 developed residential tiles at level 2 or higher`),goal('Water and power the taller homes',homes.length>0&&homes.every(t=>t.watered&&t.powered),`${homes.filter(t=>t.watered&&t.powered).length} / ${homes.length} taller home tiles served`),goal('Keep a §5,000 reserve',c.funds>=5000,`§${Math.round(c.funds).toLocaleString()} treasury`)];}
 if(s.id==='roomToGrow')return[goal('Create room for 26,000 residents',c.stats.residentialCap.limit>=26000,`${c.stats.residentialCap.limit.toLocaleString()} / 26,000 residential capacity`),goal('Welcome 200 more residents',c.stats.population>=25200,`${c.stats.population.toLocaleString()} / 25,200 residents`),goal('Keep a §5,000 reserve',c.funds>=5000,`§${Math.round(c.funds).toLocaleString()} treasury`)];
 if(s.id==='firstRepayment')return[goal('Reach the first repayment date',c.month-s.startMonth>=12,`${Math.min(12,c.month-s.startMonth)} / 12 months`),goal('Pay the original loan installment',c.finance.loans.some(l=>l.id===1&&l.paymentsMade>=1)&&c.finance.totalLoanPaid>=3750,`§${Math.round(c.finance.totalLoanPaid).toLocaleString()} repaid; §3,750 required`),goal('Avoid additional borrowing',c.finance.nextLoanId===2,'Only the original loan may have been issued.'),goal('Preserve at least 224 residents',c.stats.population>=224,`${c.stats.population} / 224 residents`),goal('Keep roads at 80% condition',c.finance.roadCondition>=80,`${Math.round(c.finance.roadCondition)}% condition`),goal('Keep §500 after the payment',c.funds>=500,`§${Math.round(c.funds).toLocaleString()} treasury`)];
 if(s.id==='waterRecovery')return[goal('Sustain recovery for six months',s.streak>=6,`${s.streak} / 6 consecutive months`),{...goal('Serve all water demand',c.stats.waterDemand>0&&c.stats.waterDemand-c.stats.waterUsed<1e-7,`${Math.max(0,c.stats.waterDemand-c.stats.waterUsed).toFixed(1)} units of unserved demand. Check the trunk pipe at 25, 17.`),area:{x:24,y:16,radius:4}},goal('Preserve at least 224 residents',c.stats.population>=224,`${c.stats.population} / 224 residents`),goal('Keep a §5,000 reserve',c.funds>=5000,`§${Math.round(c.funds).toLocaleString()} treasury`)];
 if(s.id==='roadless')return[goal('Keep the city free of roads',c.stats.roads===0,`${c.stats.roads} road tiles. Checked each month; a violation ends the challenge.`),goal('Complete two roadless years',c.month-s.startMonth>=24,`${Math.min(24,c.month-s.startMonth)} / 24 months`)];
 if(s.id==='harbor')return[goal('Sustain harbor recovery for six months',s.streak>=6,`${s.streak} / 6 consecutive months`),{...goal('Restore the original harbor',harborReady(c),'Reconnect water at 20, 21; keep power and road access at the harbor.'),area:{x:10,y:22,radius:4}},goal('House at least 400 residents',c.stats.population>=400,`${c.stats.population} / 400 residents`),goal('Keep a §5,000 reserve',c.funds>=5000,`§${Math.round(c.funds).toLocaleString()} treasury`)];
 if(s.id==='pollution')return[goal('Hold recovery for six months',s.streak>=6,`${s.streak} / 6 consecutive months`),goal('Remove every toxic-waste plant',businessRoots(c).every(t=>t.type!=='toxicWaste'),'Accepted permits may remain, but no plant may stand.'),goal('House at least 400 residents',c.stats.population>=400,`${c.stats.population} / 400 residents`),goal('Reduce average air pollution to 15 or less',c.stats.averagePollution<=15,`${c.stats.averagePollution.toFixed(1)} / 100 across zoned land`),goal('Keep a §5,000 cash reserve',c.funds>=5000,`§${Math.round(c.funds).toLocaleString()} treasury`)];
 if(s.id==='growth')return[goal('Reach 400 residents',c.stats.population>=400,`${c.stats.population} / 400 residents`),goal('Power every occupied lot',powered,`${live.filter(t=>t.powered).length} / ${live.length} occupied lots powered`),goal('Keep the treasury nonnegative',c.funds>=0,`§${Math.round(c.funds).toLocaleString()}`)];
 if(s.id==='recovery')return[goal('Complete the scheduled fire',s.eventFired&&!c.emergency.active, s.eventFired?c.emergency.active?'Emergency in progress':'Emergency ended':'Fire scheduled for month 3'),goal('Clear all rubble',c.stats.rubbleTiles===0,`${c.stats.rubbleTiles} damaged tiles remaining`),goal('Restore 224 residents',c.stats.population>=224,`${c.stats.population} / 224 residents`),goal('Keep the treasury nonnegative',c.funds>=0,`§${Math.round(c.funds).toLocaleString()}`)];
 return[goal('Maintain the recovery for six months',s.streak>=6,`${s.streak} / 6 consecutive months`),goal('Restore roads to at least 80% condition',c.finance.roadCondition>=80,`${Math.round(c.finance.roadCondition)}% condition`),goal('House at least 200 residents',c.stats.population>=200,`${c.stats.population} / 200 residents`),goal('Run an operating surplus with cash available',c.stats.balance>0&&c.funds>=0,`§${Math.round(c.stats.balance)} monthly balance · §${Math.round(c.funds)} treasury`)];
}
export function freshScenario(id){if(!Object.hasOwn(SCENARIOS,id))throw Error('Unknown scenario.');return{id,status:'playing',startMonth:0,lastChecked:0,streak:0,eventFired:false,endedMonth:null,rank:null};}
export function advanceScenario(c){const s=c.scenario;if(!s||s.status!=='playing'||s.lastChecked>=c.month)return false;s.lastChecked=c.month;if(s.id==='custom')advanceCustomStreak(c);if(s.id==='restorePeace')s.streak=c.emergency.contained>=1&&!c.emergency.active&&c.stats.rubbleTiles===0&&c.stats.population>=224&&c.stats.averageCrime<=15&&c.funds>=1500?s.streak+1:0;if(s.id==='waterRecovery')s.streak=waterRecoveryReady(c)?s.streak+1:0;if(s.id==='pollution')s.streak=businessRoots(c).every(t=>t.type!=='toxicWaste')&&c.stats.population>=400&&c.stats.averagePollution<=15&&c.funds>=5000?s.streak+1:0;if(s.id==='harbor')s.streak=harborReady(c)&&c.stats.population>=400&&c.funds>=5000?s.streak+1:0;if(s.id==='streets')s.streak=c.finance.roadCondition>=80&&c.stats.population>=200&&c.stats.balance>0&&c.funds>=0?s.streak+1:0;const ending=scenarioEnding(s),elapsed=c.month-s.startMonth,win=(s.id!=='custom'||s.definition.completionMode!=='scripted')&&scenarioGoals(c).every(g=>g.done);if(s.id==='roadless'&&c.stats.roads>0){s.status='lost';s.rank='Loser';}else if(ending&&ending.month===c.month){s.status=ending.outcome;s.rank=s.status==='won'?(elapsed<=scenarioDefinition(s).months/2?'Distinguished mayor':'Mayor'):'Try again';}else if(win&&elapsed<=scenarioDefinition(s).months){s.status='won';s.rank=s.id==='roadless'?'Winner':elapsed<=scenarioDefinition(s).months/2?'Distinguished mayor':'Mayor';}else if(elapsed>=scenarioDefinition(s).months){s.status='lost';s.rank='Try again';}else return false;s.endedMonth=c.month;awardScenarioRank(c);s.resultGoals=captureResultGoals(scenarioGoals(c));return true;}
export function validateScenario(v,month,size=48,version=126){if(v===null||v===undefined)return null;if((v.id!=='custom'&&!Object.hasOwn(SCENARIOS,v.id))||!['playing','won','lost'].includes(v.status)||!Number.isInteger(v.startMonth)||v.startMonth<0||v.startMonth>month||!Number.isInteger(v.lastChecked)||v.lastChecked<v.startMonth||v.lastChecked>month||!Number.isInteger(v.streak)||v.streak<0||v.streak>month||typeof v.eventFired!=='boolean'||(v.status==='playing'?(v.endedMonth!==null||v.rank!==null):(!Number.isInteger(v.endedMonth)||v.endedMonth<v.startMonth||v.endedMonth>month||(v.id==='custom'?(typeof v.rank!=='string'||!v.rank||v.rank.length>60):v.id==='roadless'?v.rank!==(v.status==='won'?'Winner':'Loser'):!['Distinguished mayor','Mayor','Try again'].includes(v.rank)))))throw Error('Invalid scenario progress.');const definition=v.id==='custom'?validateCustomDefinition(v.definition,size):null;const eventStates=definition?validateEventProgress(v.events,definition,v.startMonth,month):[],programHistory=definition?validateProgramInvocations(v.programInvocations,definition,eventStates,v.startMonth,month):{invocations:[],sources:[]};const ending=definition?scenarioEnding({...v,definition,programInvocations:programHistory.invocations}):null;if(ending&&(v.status!==ending.outcome||v.endedMonth!==ending.month))throw Error('Invalid scripted scenario ending.');const resultGoals=validateResultGoals(v.resultGoals,v.status,size,version);return{...(resultGoals?{resultGoals}:{}),...(definition?{definition,textOverrides:validateTextOverrides(v.textOverrides,[...definition.events.map((e,i)=>({e,state:eventStates[i]})),...programHistory.sources]),...(definition.programs?{programInvocations:programHistory.invocations}:{}),goalMarks:validateGoalMarks(v.goalMarks,definition,v.startMonth,month,eventStates,v.stageCompletedMonths,programHistory.sources),goalActivatedMonths:validateGoalActivations(v.goalActivatedMonths,definition,v.startMonth,v.lastChecked,eventStates,v,programHistory.sources),startingCity:validateScenarioStart(v.startingCity,v.startMonth,size),rankOutcome:validateRankOutcome(v.rankOutcome,definition,v.status,v.rank),variables:v.variables===undefined&&v.definition.variables===undefined?definition.variables.map(v=>v.initial):validateVariableValues(v.variables),stageCompletedMonths:validateStageProgress(v.stageCompletedMonths,definition,v.startMonth,v.lastChecked,v.streak,v.status,!!ending&&ending.outcome==='won'),events:eventStates}:{}),id:v.id,status:v.status,startMonth:v.startMonth,lastChecked:v.lastChecked,streak:v.streak,eventFired:v.eventFired,endedMonth:v.endedMonth,rank:v.rank};}

export function scenarioDefinition(s){return s.id==='custom'?{...s.definition,description:s.definition.completionMode==='scripted'?'Progress goals are tracked, but only an End scenario event grants victory. The deadline remains a loss if no ending triggers.':s.definition.objectiveMode==='sequence'?`Complete ${s.definition.objectives.length} stages in order, holding each for ${s.definition.holdMonths} consecutive months. Completed stages stay complete.`:s.definition.holdMonths>1?`Meet every goal for ${s.definition.holdMonths} consecutive months before the deadline.`:'Meet every goal before the deadline. Goals are checked together at the end of each month.',briefing:(s.textOverrides?.briefing??s.definition.briefing)||'A challenge created from your city. City-file exports preserve its goals, deadline and current progress.'}:SCENARIOS[s.id];}
